fn bitwise_and(x1: &Vec<u8>, x2: &Vec<u8>) -> Vec<u8> {
    // Since we assume x1 and x2 have the same length,
    // create a new vector by zipping the inputs and
    // applying bitwise AND to each pair of elements.
    x1.iter()
      .zip(x2.iter())
      .map(|(&a, &b)| a & b)
      .collect()
}